import numpy as np

def f(x, y):
    return 3*(x**2 + y**2) + 15*(x**2 * y**2) - (4*x*y + 1)**2

def check_n(n):
    # Try to find n distinct positive reals
    # Use a grid search or random search
    for _ in range(100000):
        a = np.random.uniform(0.01, 10, n)
        # Ensure they are distinct
        if len(set(a.round(6))) < n:
            continue

        possible = True
        for i in range(n):
            for j in range(i + 1, n):
                if f(a[i], a[j]) < 0:
                    possible = False
                    break
            if not possible:
                break
        if possible:
            return True, a
    return False, None

