import numpy as np

def g(u, v):
    return 3*np.cosh(u-v) - np.cosh(u+v)

def check_n_large(n):
    # Try many random points and use a clique-finding heuristic
    for _ in range(1000):
        # Sample points in a range that includes small and large values
        # and both positive and negative values
        points = np.concatenate([
            np.random.uniform(-3, 3, 200),
            np.random.uniform(-10, 10, 200)
        ])
        points = np.unique(points)
        num_points = len(points)
        adj = np.zeros((num_points, num_points), dtype=bool)
        for i in range(num_points):
            for j in range(i + 1, num_points):
                if g(points[i], points[j]) >= 4:
                    adj[i, j] = adj[j, i] = True

        # Heuristic: find a clique
        # 1. Find nodes with high degree
        degrees = np.sum(adj, axis=1)
        nodes = np.argsort(degrees)[::-1]

        for i in range(len(nodes)):
            clique = [nodes[i]]
            for j in range(i + 1, len(nodes)):
                v = nodes[j]
                if all(adj[v, c] for c in clique):
                    clique.append(v)
                    if len(clique) == n:
                        return True, points[clique]
    return False, None

for n in range(1, 6):
    res, u = check_n_large(n)
    print(f"n={n}: {res}, {u}")

