from scipy.optimize import minimize

def g(u, v):
    return 3*np.cosh(u-v) - np.cosh(u+v)

def objective(u):
    u = u.reshape(-1, 1)
    violations = []
    for i in range(len(u)):
        for j in range(i + 1, len(u)):
            violations.append(4 - g(u[i][0], u[j][0]))
    return -max(violations)

for n in range(4, 5):
