import numpy as np
from scipy.optimize import minimize

def g(u, v):
    return 3*np.cosh(u-v) - np.cosh(u+v)

def objective(u):
    max_v = -1e18
    for i in range(len(u)):
        for j in range(i + 1, len(u)):
            v = 4 - g(u[i], u[j])
            if v > max_v:
                max_v = v
    return max_v

for n in range(4, 5):
    found = False
    for _ in range(20):
        u0 = np.random.uniform(-2, 2, n)
        res = minimize(objective, u0, method='Nelder-Mead')
        if res.fun <= 1e-7:
            print(f"n={n}: Found! {res.x}")
            found = True
            break
    if not found:
        print(f"n={n}: Not found")
